package dev.zomboid.mts;
import java.util.*;import minecrafttransportsimulator.entities.instances.*;
public class WorkshopChecks {public static class Rider {public int hits;public double amount;public void attack(minecrafttransportsimulator.baseclasses.Damage d){hits++;amount=d.amount;}}static int n;static void check(boolean b,String m){n++;if(!b)throw new AssertionError(m);}public static void main(String[]args){EntityVehicleF_Physics car=new EntityVehicleF_Physics();check(RoadPhysics.soft("minecraft:oak_leaves"),"leaves are soft");check(RoadPhysics.soft("minecraft:moss_block"),"moss is soft");check(!RoadPhysics.soft("minecraft:mossy_cobblestone"),"mossy stone remains hard");check(RoadPhysics.maximumStep(10,.5)==1,"step including wheel radius capped to 1.5");check(RoadPhysics.maximumStep(1,.5)==1,"small wheel settings preserved");check(RoadPhysics.tilt(20,0,true)==.75,"gradual pitch");check(Math.abs(RoadPhysics.tilt(20,21.8,true)-.2)<.001,"pitch capped to 22 degrees");check(RoadPhysics.tilt(20,35,false)==-.75,"old excessive roll corrected gradually");car.velocity=3;RoadPhysics.begin(car);car.world.name="minecraft:oak_leaves";check(RoadPhysics.hardness(car.world,new Checks.Point(0,0,0),car)==0,"soft obstacles break without resistance");Maintenance.collision(true,car,new Checks.Box(),true);check(car.damageVar.currentValue==0,"leaves do not damage car");RoadPhysics.begin(car);car.world.name="minecraft:stone";RoadPhysics.hardness(car.world,new Checks.Point(0,0,0),car);Maintenance.collision(true,car,new Checks.Box(),true);check(car.damageVar.currentValue>0&&car.damageVar.currentValue<=car.definition.general.health*.06,"stone damages car with prior six percent cap");check(Workshop.band(null)==3&&Workshop.band(90d)==0&&Workshop.band(50d)==1&&Workshop.band(10d)==2,"condition colours include missing part");Checks.Slot slot=new Checks.Slot();slot.types.add("ground_wheel");car.definition.parts.add(slot);car.partsInSlots.add(null);List<Workshop.Entry> rows=Workshop.equipment(car);check(rows.get(0).condition()==null,"missing wheel shown as absent, not full health");PartEngine part=new PartEngine();car.partsInSlots.set(0,part);check(Workshop.equipment(car).get(0).condition()==100,"installed part condition read from native damage");car.definition.packID="belroftmotors";car.definition.systemName="adventure";check(Mechanics.car(car),"Belroft road car integrated");car.definition.systemName="corallum";check(!Mechanics.car(car),"Belroft boat physics preserved");double[] bounce=CrashResponse.rebound(0,3,0,1,.35);check(bounce[1]<0&&Math.abs(bounce[1]*.35)<=.150001,"heavy frontal collision reverses with bounded recoil");check(Math.hypot(bounce[0],bounce[1])<3,"impact dissipates energy");double[] glancing=CrashResponse.rebound(1,3,0,1,.35);check(glancing[0]>0&&glancing[0]<1,"glancing collision preserves damped sideways movement");check(CrashResponse.injury(1)==0&&CrashResponse.injury(6)==8,"heavy collision occupant injury is capped; light bump safe");car.definition.systemName="adventure";car.allParts.clear();Rider rider=new Rider();APart seat=new APart();seat.rider=rider;car.allParts.add(seat);car.allParts.add(seat);CrashResponse.impact(car,6);check(rider.hits==1&&rider.amount==8,"native damage applied once per occupant");check(EngineResponse.rise(7000,.5,180,2400,2)<EngineResponse.rise(7000,1.3,180,1200,2),"heavy weak car revs slower than powerful light car");check(EngineResponse.rise(7000,1,300,1200,2)<EngineResponse.rise(7000,1,100,1200,2),"larger engine inertia slows RPM rise");check(EngineResponse.rise(7000,1,180,2400,.7)<EngineResponse.rise(7000,1,180,2400,3),"higher gears carry more load");PartEngine motor=new PartEngine();motor.vehicleOn=car;motor.running=true;motor.rpm=1000;check(EngineResponse.limit(7000,motor)<1200,"native running engine RPM surge limited");check(EngineResponse.limit(700,motor)==700,"gear shift RPM drop remains immediate");motor.running=false;check(EngineResponse.limit(1300,motor)==1300,"starter unaffected");CrashResponse.begin(car);Object box=new Object(){public Checks.Point currentCollisionDepth=new Checks.Point(0,0,1);};CrashResponse.blocked(car,box,true);CrashResponse.impact(car,6);CrashResponse.finish(car);check(car.motion.z<0,"queued rebound applies after native collision clipping");check(RoadPhysics.clearance(2,new Object(){public EntityVehicleF_Physics vehicle=car;})==1.5,"oversize wheel minimum offset cannot exceed 1.5");System.out.println("Workshop/terrain checks: "+n);}}
